{
  "id": "V020",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "이번 주 고객 의견 경향을 회의용으로 요약하려는 목적이 보존됩니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "의견을 검토하고 주제별 경향을 분석해 요약 자료를 만드는 작업이 보존됩니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "고객 의견의 반복되는 요구와 불편 주제가 보존됩니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "매주 접수한 고객 의견, 특히 이번 주 의견이 보존됩니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "각 경향을 뒷받침하는 의견을 포함한 요약 자료가 보존됩니다."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "개별 고객 답장과 제품 개선 효과 예측 제외가 보존됩니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가하지 않았습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "서비스 기획팀이 의견을 검토하고 자료를 회의에 사용한다는 역할이 보존됩니다."
    }
  ],
  "issues": [],
  "permission_interpretation": "개별 고객에게 답장하거나 제품 개선 효과를 예측하는 작업은 제외된다는 뜻이며, 특정 주체에게 해당 행위의 수행을 요구하거나 허용하지 않습니다."
}
